#Requires -Version 5.1
# fix-pdf-fotos-comprimidas.ps1
# El PDF ocupaba 34 MB porque las fotos de movil (3-8 MB cada una)
# se insertaban sin comprimir. Fix: usar sharp (incluido en Next.js 14)
# para redimensionar a max 1200px y comprimir a JPEG 72% antes de insertar.
# Una foto tipica pasa de 5 MB a 150-250 KB -> PDF con 2 fotos ~1-2 MB.
# Lo mismo se aplica a los adjuntos del email.

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix PDF fotos comprimidas" -ForegroundColor Cyan

Write-Host "  -> src\lib\pdf\generatePartePdf.ts" -ForegroundColor Gray
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\lib\pdf\generatePartePdf.ts"), $bytes)
Write-Host "  OK: 11 KB escrito" -ForegroundColor Green

Write-Host "  -> src\app\api\partes\email\route.ts" -ForegroundColor Gray
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\api\partes\email\route.ts"), $bytes)
Write-Host "  OK: 7 KB escrito" -ForegroundColor Green

Write-Host ""
Write-Host "  Verificando..." -ForegroundColor Cyan
$pdf = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\lib\pdf\generatePartePdf.ts"), [System.Text.Encoding]::UTF8)
$email = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\api\partes\email\route.ts"), [System.Text.Encoding]::UTF8)
if ($pdf.Contains('sharp(rawBuf)') -and $pdf.Contains('jpeg({ quality: 72')) { Write-Host "  OK: PDF comprime fotos con sharp" -ForegroundColor Green } else { Write-Host "  ERROR PDF" -ForegroundColor Red }
if ($email.Contains('sharp(rawBuf)') -and $email.Contains('jpeg({ quality: 75')) { Write-Host "  OK: Email comprime fotos con sharp" -ForegroundColor Green } else { Write-Host "  ERROR Email" -ForegroundColor Red }
Write-Host ""
Write-Host '  git add src\lib\pdf\generatePartePdf.ts src\app\api\partes\email\route.ts'
Write-Host '  git commit -m "fix: comprimir fotos en PDF y email con sharp - de 34MB a ~1-2MB"'
Write-Host '  git push'
